/**
 * The app's "server": the project's own API route handlers, run in the WebView.
 * `apiFetch('/api/...')` lands here instead of the network (see apiClient.ts).
 * The table of routes is generated by scripts/package-android.mjs from app/api.
 */
import { API_ROUTES } from './routes.generated';

type RouteHandler = (
    request: Request,
    context: { params: Promise<Record<string, string>> },
) => Response | Promise<Response>;

export interface ApiRoute {
    pattern: RegExp;
    keys: string[];
    module: Record<string, unknown>;
}

/** Served by the Kotlin shell (streaming, byte ranges), never by JS. */
export function isNativeApiPath(path: string): boolean {
    return /^\/api\/(relay|vod)(\/|\?|$)/.test(path);
}

function jsonError(message: string, status: number): Response {
    return new Response(JSON.stringify({ error: message }), {
        status,
        headers: { 'content-type': 'application/json' },
    });
}

export async function handleLocalApi(path: string, init: RequestInit): Promise<Response> {
    const url = new URL(path, window.location.origin);
    const method = (init.method || 'GET').toUpperCase();

    for (const route of API_ROUTES as ApiRoute[]) {
        const match = route.pattern.exec(url.pathname);
        if (!match) continue;

        const handler = route.module[method] as RouteHandler | undefined;
        if (typeof handler !== 'function') return jsonError('Method not allowed', 405);

        const params: Record<string, string> = {};
        route.keys.forEach((key, index) => {
            params[key] = decodeURIComponent(match[index + 1]);
        });

        try {
            const request = new Request(url.toString(), {
                method,
                headers: init.headers,
                body: method === 'GET' || method === 'HEAD' ? undefined : init.body,
                signal: init.signal,
            });
            return await handler(request, { params: Promise.resolve(params) });
        } catch (error) {
            console.error(`[LocalApi] ${method} ${url.pathname} failed`, error);
            return jsonError('Internal error', 500);
        }
    }

    return jsonError('Not found', 404);
}
